@spec vm_snap_temper_spec  src=tests/specs/vm_snap_temper_spec.lua  loc=181  cases=10
@exercises tuning (tuning), trackerView (h.vm), editCursor (h.ec), configManager (h.cm)
@surface   tuning.derive, vm:setGridSize, tuning.stepToMidi, vm:retune, ec:setSelection, cm:set, cm:getAt
@harness   mk{seed.notes}

# Intent
  Retune: tv:retune(slots) runs every note in scope through tuning.snap and
  writes the pair back, strength being how far of the way there it actually
  lands, and remembers the target and key on the take. The temper is a
  twelve-note quarter-comma meantone MOS, so a step's seat carries a detune of
  its own and the window is asymmetric (+38.0 / -58.6 either side of step 1).

# Helpers
  @fn mk(harness, notes)  @ 24-31
  @fn note(ppq, pitch, detune)  @ 33-36
  @fn lane1(h)  @ 38-42
  @fn cell(h, row)  @ 44
  @fn near(a, b, msg)  @ 46-48
  @fn seat(step, oct)  @ 51
      -- Seat of (step, octave) under MEAN, as the spec's expectation frame.

# Cases
  @case 'retune(all) seats an off-step note on its own step'  [harness]  @ 55-64
  @case 'a note past the half-way point lands on its neighbour'  [harness]  @ 68-77
  @case 'a note inside the window keeps its step'  [harness]  @ 81-88
  @case 'a note already on its step is left where it is'  [harness]  @ 92-100
  @case 'a selection confines the snap to the notes inside it'  [harness]  @ 104-113
  @case 'half strength closes half the distance, and again on the next run'  [harness]  @ 117-127
  @case 'a blend below full strength is re-seated on the nearest semitone'  [harness]  @ 131-141
  @case 'zero strength moves nothing, not even the written pitch'  [harness]  @ 145-153
  @case 'retune remembers the target and the key on the take'  [harness]  @ 157-169
  @case 'retune with no target forgets the one the take carried'  [harness]  @ 173-179

# Uses (outbound edges)
  @use call tuning.derive  @ 10,18
  @use call vm:setGridSize  @ 29
  @use call tuning.stepToMidi  @ 51
  @use call vm:retune  @ 58,72,84,96,109,122,124,136,149,161,177
  @use call ec:setSelection  @ 107
  @use call cm:set  @ 160,176
  @use call cm:getAt  @ 163,164,165,178

